output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "Customers are obliged to take the cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Customers are prohibited from picking up shelf items unless they are pushing a cart and their hands are free.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "bad_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "or": [
                  {
                    "not": "with_cart"
                  },
                  {
                    "not": "hands_free"
                  }
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bad_item_pickup"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Customers are obliged to park the cart at the return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "with_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "park_cart_at_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "park_cart_at_return_bay"
    }
  },
  {
    "id": "checkout_unencumbered",
    "text": "Customers are prohibited from entering the checkout and exit zone while pushing a cart or carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "checkout_exit_zone": {
          "or": [
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "checkout_exit_zone",
          "encumbered"
        ]
      }
    }
  },
  {
    "id": "reclaim_temporary_cart_drop",
    "text": "If a customer temporarily puts the cart down outside the return bay, they are obliged to reclaim a cart before exiting.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        },
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "temporary_cart_drop": {
          "pre": {
            "and": [
              "outside_return_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "without_cart"
        },
        "reclaim_cart": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop",
      "discharge": "reclaim_cart"
    }
  },
  {
    "id": "egg_area_middle_cart_check",
    "text": "After taking an item from the egg area, customers are obliged to perform a cart set-down check at the middle aisle cell.",
    "abstraction": {
      "state_properties": {
        "egg_area": {
          "or": [
            "at(6,4)",
            "at(6,2)"
          ]
        },
        "middle_aisle_check_spot": "at(3,4)",
        "with_cart": "hasCart",
        "cart_at_middle_aisle": "cartAt(3,4)"
      },
      "events": {
        "pickup_from_egg_area": {
          "pre": {
            "and": [
              "egg_area",
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "with_cart"
        },
        "middle_aisle_cart_check": {
          "pre": {
            "and": [
              "middle_aisle_check_spot",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_middle_aisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_from_egg_area",
      "discharge": "middle_aisle_cart_check"
    }
  },
  {
    "id": "inspect_foyer_before_cart",
    "text": "Customers are obliged to step into the foyer cell north of the entrance while not holding a cart during the entry phase.",
    "abstraction": {
      "state_properties": {
        "start_cell_without_cart": {
          "and": [
            "at(0,5)",
            {
              "not": "hasCart"
            }
          ]
        },
        "foyer_inspection_cell": "at(0,4)"
      },
      "events": {
        "step_into_foyer_without_cart": {
          "pre": {
            "and": [
              "start_cell_without_cart",
              "N"
            ]
          },
          "post": "foyer_inspection_cell"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "step_into_foyer_without_cart"
    }
  },
  {
    "id": "inspect_far_side_of_cart_station",
    "text": "Customers are obliged to inspect the cell immediately east of the entrance cart station while not yet pushing the cart.",
    "abstraction": {
      "state_properties": {
        "at_cart_station_without_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)",
            {
              "not": "hasCart"
            }
          ]
        },
        "far_side_of_entrance_cart": {
          "and": [
            "at(2,5)",
            "cartAt(1,5)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "inspect_far_side_of_cart_station": {
          "pre": {
            "and": [
              "at_cart_station_without_cart",
              "E"
            ]
          },
          "post": "far_side_of_entrance_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "inspect_far_side_of_cart_station"
    }
  }
]
